@startuml

class Aircraft {
  + name : string
  + type : string
  + yearOfManufacture : int
  + nextInspectionDate : date
}

class PassengerAircraft extends Aircraft {
  + numberOfSeats : int
}

class SeatCategory {
  + designation : string
  + offersEntertainment : boolean
  + numberOfSeats : int
}

class Flight {
  + flightNumber : string
  + date : date
}

class Passenger {
  + name : string
  + passportNumber : string
}

class Ticket {
  + ticketNumber : string
  + price : float
  + upgradeDesired : boolean
}

class Airline {
  + name : string
}

class FlightAttendant {
  + name : string
  + employmentDate : date
  + isChiefStewardess : boolean
}

class Pilot {
  + name : string
  + employmentDate : date
  + license : string
}

class Airport {
  + name : string
  + address : string
  + numberOfRunways : int
}

Airline "0..1" -- "*" Aircraft : belongs to
Airline "1" -- "*" FlightAttendant : employs
Airline "1" -- "*" Pilot : employs
PassengerAircraft "1" -- "*" SeatCategory : has
Flight "*" -- "1" Aircraft : performs
Flight "1" -- "*" Passenger : involves
Flight "1" -- "*" Ticket : has
Passenger "1" -- "*" Ticket : holds
SeatCategory "1" -- "*" Ticket : assigned to
Flight "*" -- "1" Airport : departs from
Flight "*" -- "1" Airport : arrives at
Aircraft "*" -- "0..1" Airport : home airport
Flight "1" -- "1..* " FlightAttendant : staffed by
Flight "1" -- "1" Pilot : captain
Flight "1" -- "1..2" Pilot : co-pilots

@enduml

